#!/usr/bin/env python3
"""Canonical, content-led structure and generated-image policy for the book."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass


@dataclass(frozen=True)
class Route:
    start: int
    end: int
    title: str
    introduction: str


@dataclass(frozen=True)
class Part:
    number: int
    title: str
    opener: str
    opener_alt: str


@dataclass(frozen=True)
class Chapter:
    number: int
    part: int
    filename: str
    title: str
    core_question: str
    introduction: str
    connection: str
    routes: tuple[Route, ...]
    project_title: str
    project: str


@dataclass(frozen=True)
class ObservationImage:
    filename: str
    alt: str
    caption: str


@dataclass(frozen=True)
class PrincipleImage:
    filename: str
    alt: str
    caption: str


