    Chapter(32, 12, "32_motion_vehicles_ships_and_flight.md", "运动、车辆、船与飞行", "人和交通工具怎样保持平衡、加速、制动、浮沉并在空气或水中运动？", "从走路和自行车的动态平衡进入驱动、刹车与信号控制，再比较火车、地铁、船、飞机、直升机、热气球和潜水艇。", "每次列出重量、支持力、摩擦、浮力或流体作用中真正相关的力，不用一个“动力”词替代全部机制。", (r(335, 340, "平衡、驱动、制动与交通控制", "身体和车辆持续调整运动，驱动与摩擦改变速度，安全带和信号系统降低风险。"), r(341, 348, "轨道、浮力、帆、翼与压载舱", "钢轨约束方向，排水产生浮力，空气动力和密度差支持多种飞行与潜航。")), "给交通工具画一张受力图", "选择静止的玩具车、纸船或交通照片，标出重力与支撑或浮力，再按正文添加必要的推进或阻力。不要在道路、水边或运行车辆旁观察。"),
