# Observable natural scenes, materials, animals, and Earth processes use
# realistic main plates. SVG art remains available only for supporting
# mechanism diagrams when a process cannot be photographed directly.
REALISTIC_MAIN_IMAGES = {
    question: f"question-{question:03d}.png"
    for question in (
        *range(1, 9),
        *range(10, 30),
        *range(31, 38),
        *range(39, 60),
        *range(116, 152),
        *range(213, 219),
        *range(220, 225),
    )
}


PART_BY_NUMBER = {part.number: part for part in PARTS}
CHAPTER_BY_QUESTION = {
    question: chapter
    for chapter in CHAPTERS
    for route in chapter.routes
    for question in range(route.start, route.end + 1)
}


def validate_structure() -> None:
    if [part.number for part in PARTS] != list(range(1, len(PARTS) + 1)):
        raise RuntimeError("part numbers must be consecutive")
    if [chapter.number for chapter in CHAPTERS] != list(range(1, len(CHAPTERS) + 1)):
        raise RuntimeError("chapter numbers must be consecutive")
    if any(chapter.part not in PART_BY_NUMBER for chapter in CHAPTERS):
        raise RuntimeError("chapter references an unknown part")
    questions = [
        question
        for chapter in CHAPTERS
        for route in chapter.routes
        for question in range(route.start, route.end + 1)
    ]
    if questions != sorted(questions) or len(questions) != len(set(questions)):
        repeated = sorted(question for question, count in Counter(questions).items() if count > 1)
        raise RuntimeError(f"question ids must be unique and increasing: repeated={repeated}")
    if questions and questions != list(range(questions[0], questions[-1] + 1)):
        missing = sorted(set(range(questions[0], questions[-1] + 1)) - set(questions))
        raise RuntimeError(f"question ids contain gaps: missing={missing}")
    if not set(OBSERVATION_IMAGES).issubset(CHAPTER_BY_QUESTION):
        raise RuntimeError("observation image references an unknown question")
    if not set(REALISTIC_PRINCIPLE_IMAGES).issubset(CHAPTER_BY_QUESTION):
        raise RuntimeError("realistic principle image references an unknown question")
    if not set(REALISTIC_MAIN_IMAGES).issubset(CHAPTER_BY_QUESTION):
        raise RuntimeError("realistic main image references an unknown question")


validate_structure()
